{"filePath":"/tmp/shot2.js","content":"async (page) => {
  const panels = page.locator('.am-panel, article section, .am-doc-panel');
  // fallback: sections with headings
  const heads = page.locator('h2');
  const n = await heads.count();
  const out = [];
  for (let i = 0; i < n; i++) {
    const title = (await heads.nth(i).innerText()).replace(/\s+/g, ' ').trim();
    const section = heads.nth(i).locator('xpath=ancestor::*[self::section or contains(@class,"panel")][1]');
    const handle = (await section.count()) ? section : heads.nth(i).locator('xpath=..');
    const safe = title.replace(/[^\w\u4e00-\u9fff]+/g, '_').slice(0, 24);
    await handle.screenshot({ path: `/tmp/v2-${i}-${safe}.png` });
    const box = await handle.boundingBox();
    out.push({ i, title, box });
  }
  const svg = page.locator('svg').first();
  const texts = await page.evaluate(() => {
    const svg = document.querySelector('svg[aria-label], .am-sequence svg, figure svg');
    if (!svg) return { missing: true, svgs: [...document.querySelectorAll('svg')].map(s => s.getAttribute('aria-label') || s.getAttribute('class')) };
    const labels = [...svg.querySelectorAll('text')].map(t => {
      const r = t.getBoundingClientRect();
      return { t: (t.textContent||'').trim(), x: r.x, y: r.y, w: r.width, h: r.height };
    }).filter(x => x.t && x.w);
    const overlaps = [];
    for (let i = 0; i < labels.length; i++) {
      for (let j = i+1; j < labels.length; j++) {
        const a = labels[i], b = labels[j];
        const ix = Math.min(a.x+a.w, b.x+b.w) - Math.max(a.x, b.x);
        const iy = Math.min(a.y+a.h, b.y+b.h) - Math.max(a.y, b.y);
        if (ix > 2 && iy > 2) overlaps.push(a.t + ' ∩ ' + b.t);
      }
    }
    const vb = svg.viewBox.baseVal;
    return { aria: svg.getAttribute('aria-label'), viewBox: `${vb.x} ${vb.y} ${vb.width} ${vb.height}`, n: labels.length, overlaps: overlaps.slice(0, 15), overlapCount: overlaps.length };
  });
  return { out, texts };
}
