    const hs = [...document.querySelectorAll('h2')];
    return hs.map((h, i) => {
      const next = hs[i + 1];
      const top = h.getBoundingClientRect().top + window.scrollY;
      const bottom = next ? next.getBoundingClientRect().top + window.scrollY : document.documentElement.scrollHeight;
      return { title: h.innerText.trim(), top, bottom, h: bottom - top };
    });
  });
  const shots = [];
  for (let i = 0; i < data.length; i++) {
    const s = data[i];
    const safe = s.title.replace(/[^\w\u4e00-\u9fff]+/g, '_').slice(0, 24);
