    await page.screenshot({
      path: `/tmp/sec-${i}-${safe}.png`,
      clip: { x: 280, y: s.top - 8, width: 980, height: Math.min(s.h + 16, 2400) },
      fullPage: true,
    });
    shots.push({ i, title: s.title, h: s.h });
  }
  return shots;
}
